package com.bank.pstrat.service;

import com.bank.pstrat.model.AccessPattern;
import com.bank.pstrat.model.PartitionScheme;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class PartitionChoiceService {
    private static final Logger log = LoggerFactory.getLogger(PartitionChoiceService.class);

    // Choose the scheme from the ACTUAL access pattern, so queries can prune.
    public PartitionScheme choose(AccessPattern p) {
        // Two dimensions (per-account AND date windows) → composite so both prune.
        if (p.highCardinalityEquality && p.alsoFiltersByDate) {
            log.info("Per-account lookups + date windows → COMPOSITE range(date)+hash(account)");
            return PartitionScheme.COMPOSITE_RANGE_HASH;
        }
        if (p.filtersByRange && "txn_date".equals(p.dominantFilterColumn)) {
            log.info("Date-window reporting → RANGE by txn_date (prunes + easy archive)");
            return PartitionScheme.RANGE;
        }
        if (p.filtersByDiscreteValue) {
            log.info("Few discrete values ({}) → LIST", p.dominantFilterColumn);
            return PartitionScheme.LIST;
        }
        if (p.highCardinalityEquality) {
            log.info("High-cardinality equality on {} → HASH (even spread, prunes to one)",
                p.dominantFilterColumn);
            return PartitionScheme.HASH;
        }
        // If queries do NOT filter on any good partition key, partitioning will NOT help.
        log.warn("No filter matches a partition key → do NOT partition; use a plain index instead");
        return PartitionScheme.NONE;
    }
}
